// Generates one HTML file per blog card. 1200x630 OG cards for ivue.
const fs = require('fs');
const path = require('path');
const outDir = __dirname;

const mark = (from, mid, to, size) => `
<svg width="${size}" height="${size}" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="ivg" x1="8" y1="14" x2="40" y2="34" gradientUnits="userSpaceOnUse">
      <stop stop-color="${from}"/>
      ${mid ? `<stop offset="0.5" stop-color="${mid}"/>` : ''}
      <stop offset="1" stop-color="${to}"/>
    </linearGradient>
  </defs>
  <path d="M24 24 C 19 17, 10.6 17.6, 10.6 24 C 10.6 30.4, 19 31, 24 24 C 29 17, 37.4 17.6, 37.4 24 C 37.4 30.4, 29 31, 24 24 Z"
        stroke="url(#ivg)" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round" fill="none"/>
</svg>`;

const head = `
<meta charset="utf-8">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@300..800&family=Geist+Mono:wght@400..700&display=swap" rel="stylesheet">
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  html,body { width:1200px; height:630px; overflow:hidden; }
  body { font-family:'Geist',sans-serif; position:relative; }
  .logo { position:absolute; left:88px; display:flex; align-items:center; gap:18px; }
  .logo .word { font-weight:700; color:#eef1fb; letter-spacing:-0.01em; }
</style>`;

function std(c) {
  return `<!doctype html><html><head><title>${c.file}</title>${head}
<style>
  body { background:
    radial-gradient(700px 520px at -4% -8%, ${c.glowTL}, transparent 62%),
    radial-gradient(950px 720px at 104% 112%, ${c.glowBR}, transparent 62%),
    linear-gradient(135deg, ${c.base1} 0%, ${c.base2} 100%); }
  .logo { top:156px; }
  .logo .word { font-size:31px; }
  .kicker { position:absolute; left:88px; top:240px; font-family:'Geist Mono',monospace;
    font-size:20px; font-weight:500; letter-spacing:0.34em; color:${c.kickerColor}; }
  h1 { position:absolute; left:88px; top:292px; width:max-content; max-width:1030px;
    font-size:75px; font-weight:700; line-height:1.27; letter-spacing:-0.015em;
    background:linear-gradient(90deg, #eef1fb 0%, #e7ecfa ${c.whiteStop}, ${c.gradA} ${c.accentStop}, ${c.gradB} 100%);
    -webkit-background-clip:text; background-clip:text; color:transparent; }
</style></head><body>
  <div class="logo">${mark(c.markFrom, c.markMid, c.markTo, 34)}<span class="word">ivue</span></div>
  <div class="kicker">${c.kicker}</div>
  <h1>${c.title}</h1>
</body></html>`;
}

function hero(c) {
  return `<!doctype html><html><head><title>${c.file}</title>${head}
<style>
  body { background:
    radial-gradient(720px 540px at -2% -6%, rgba(139,124,246,.16), transparent 62%),
    radial-gradient(950px 720px at 104% 112%, rgba(45,212,191,.16), transparent 62%),
    linear-gradient(135deg, #12173a 0%, #0b1024 55%, #0a1122 100%); }
  .logo { top:100px; }
  .logo .word { font-size:40px; }
  h1 { position:absolute; left:88px; top:190px; font-size:82px; font-weight:700;
    line-height:1.13; letter-spacing:-0.015em; color:#e9edfa; }
  h1 .grad { background:linear-gradient(90deg, #8b7cf6 0%, #4f8ef7 35%, #2dd4bf 72%, #34d399 100%);
    -webkit-background-clip:text; background-clip:text; color:transparent; }
  .meta { position:absolute; left:88px; top:508px; display:flex; gap:46px;
    font-size:27px; color:#8b93b8; font-weight:400; }
  .meta b { color:#e9edfa; font-weight:700; }
</style></head><body>
  <div class="logo">${mark('#38BDF8','#2DD4BF','#34D399', 40)}<span class="word">ivue</span></div>
  <h1>Plain classes.<br>Full reactivity.<br><span class="grad">One kilobyte.</span></h1>
  <div class="meta">
    <span><b>1.1 kB</b> gzipped</span>
    <span><b>0</b> dependencies</span>
    <span><b>100%</b> test coverage</span>
    <span><b>22 ms</b> / 1M instances</span>
  </div>
</body></html>`;
}

const D = { base1:'#0d1228', base2:'#0a0e1e', whiteStop:'28%', accentStop:'68%' };
const cards = [
  { file:'computed-is-a-cache', kicker:'THE HERESY', kickerColor:'#2dd4bf',
    title:'computed() is a cache,<br>not a derivation.',
    gradA:'#6ee7b7', gradB:'#34d399', markFrom:'#38BDF8', markMid:'#2DD4BF', markTo:'#34D399',
    glowTL:'rgba(45,212,191,.10)', glowBR:'rgba(37,99,235,.16)', ...D },
  { file:'hot-reload-for-logic', kicker:'CLASS HMR', kickerColor:'#fbbf24',
    title:'Hot reload was never<br>about components.',
    gradA:'#fde68a', gradB:'#f6ad10', markFrom:'#a5b4fc', markTo:'#f59e0b',
    glowTL:'rgba(251,191,36,.15)', glowBR:'rgba(99,102,241,.13)', ...D },
  { file:'inheritance-exile', kicker:'SUPER, REACTIVE', kickerColor:'#fb7185',
    title:"Inheritance didn't<br>deserve the exile.",
    gradA:'#fda4af', gradB:'#fb7185', markFrom:'#f59e0b', markTo:'#fb7185',
    glowTL:'rgba(251,113,133,.11)', glowBR:'rgba(234,179,8,.07)', ...D },
  { file:'measured-not-promised', kicker:'BENCHMARKS WITH RECEIPTS', kickerColor:'#94a3b8',
    title:'Measured,<br>not promised.',
    gradA:'#e2e7f6', gradB:'#dde3f4', markFrom:'#818cf8', markTo:'#a5b4fc',
    glowTL:'rgba(148,163,184,.08)', glowBR:'rgba(59,130,246,.15)', ...D },
  { file:'one-kilobyte-feature', kicker:'LESS IS THE FEATURE', kickerColor:'#a78bfa',
    title:'One kilobyte<br>is a feature.',
    gradA:'#ddd6fe', gradB:'#cfc4fb', markFrom:'#38BDF8', markMid:'#2DD4BF', markTo:'#34D399',
    glowTL:'rgba(167,139,250,.11)', glowBR:'rgba(45,212,191,.11)', ...D },
  { file:'organs-not-skeletons', kicker:'COMPOSABLES, HOSTED', kickerColor:'#34d399',
    title:'Composables are organs,<br>not skeletons.',
    gradA:'#a7f3d0', gradB:'#34d399', markFrom:'#2DD4BF', markTo:'#34D399',
    glowTL:'rgba(52,211,153,.08)', glowBR:'rgba(45,212,191,.09)', base1:'#0a1322', base2:'#091020',
    whiteStop:'28%', accentStop:'68%' },
  { file:'rented-objects', kicker:'THE MODEL LAYER', kickerColor:'#818cf8',
    title:'Your objects are rented<br>from the framework.',
    gradA:'#818cf8', gradB:'#c084fc', markFrom:'#c084fc', markTo:'#f472b6',
    glowTL:'rgba(129,140,248,.11)', glowBR:'rgba(244,114,182,.13)', ...D },
  { file:'scrollbar-is-code', kicker:'VIRTUAL EVERYTHING', kickerColor:'#818cf8',
    title:'The scrollbar<br>is code.',
    gradA:'#a5b4fc', gradB:'#b4c0ff', markFrom:'#38bdf8', markTo:'#3b82f6',
    glowTL:'rgba(129,140,248,.09)', glowBR:'rgba(56,189,248,.11)', ...D },
  { file:'this-method-era', kicker:'BOUND METHODS', kickerColor:'#38bdf8',
    title:'this.method,<br>finally safe to pass.',
    gradA:'#7dd3fc', gradB:'#38bdf8', markFrom:'#a5b4fc', markTo:'#818cf8',
    glowTL:'rgba(96,165,250,.11)', glowBR:'rgba(99,102,241,.11)', ...D },
  { file:'twenty-million-cells', kicker:'THE FLYWEIGHT', kickerColor:'#22d3ee',
    title:'The 20,000,000-cell<br>document.',
    gradA:'#7dd3fc', gradB:'#38bdf8', markFrom:'#38bdf8', markTo:'#818cf8',
    glowTL:'rgba(56,189,248,.09)', glowBR:'rgba(129,140,248,.11)', ...D },
];

for (const c of cards) fs.writeFileSync(path.join(outDir, c.file + '.html'), std(c));
fs.writeFileSync(path.join(outDir, 'introducing-ivue.html'), hero({ file:'introducing-ivue' }));
console.log('generated', cards.length + 1, 'html files');

