async (page) => {
  await page.goto('about:blank');
  await page.goto('http://localhost:4180/ivue/');
  await page.waitForTimeout(1200);
  if (await page.evaluate(() => document.documentElement.classList.contains('dark'))) {
    await page.locator('.VPSwitchAppearance').first().click(); await page.waitForTimeout(700);
  }
  const cell = page.locator('.ix-moat .cell').first();
  await cell.scrollIntoViewIfNeeded();
  await cell.hover(); await page.waitForTimeout(400);
  const info = await cell.evaluate((el) => {
    const cs = getComputedStyle(el);
    // any matching hover rules from all sheets
    const rules = [];
    for (const sheet of document.styleSheets) {
      let list; try { list = sheet.cssRules; } catch { continue; }
      for (const rule of list) {
        if (rule.selectorText?.includes('.cell:hover') || (rule.selectorText?.includes(':hover') && el.matches(rule.selectorText.replace(/:hover/g, '')))) {
          rules.push(rule.selectorText + ' → bg:' + rule.style.backgroundColor + ' filter:' + rule.style.filter + ' shadow:' + (rule.style.boxShadow||''));
        }
      }
    }
    return { bg: cs.backgroundColor, filter: cs.filter, shadow: cs.boxShadow.slice(0,80), rules: rules.slice(0,6) };
  });
  const box = await cell.boundingBox();
  await page.screenshot({ path: 'tmp/moat-hover.png', clip: { x: box.x - 20, y: box.y - 20, width: 700, height: 220 } });
  return JSON.stringify(info, null, 1);
}

