async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('http://localhost:4212/#/virtual-scroller');
  await page.waitForTimeout(1200);
  const btn = page.locator('nav button', { hasText: 'autoplay' }).first();
  out.initialLabel = await btn.innerText();
  // start autoplay
  await btn.click();
  await page.waitForTimeout(300);
  out.playingLabel = await btn.innerText();
  const posA = await page.evaluate(() => document.querySelector('.example-body [class*=inner], .example-body > div > div')?.style?.transform ?? 'n/a');
  // let it creep ~2.5s
  await page.waitForTimeout(2500);
  const firstRow = await page.locator('.row b').first().innerText();
  out.afterCreepFirstRow = firstRow;
  // wheel UP over the list → should stop autoplay reactively
  const body = page.locator('.example-body');
  await body.hover();
  await page.mouse.wheel(0, -300);
  await page.waitForTimeout(600);
  out.labelAfterScrollUp = await btn.innerText();
  out.stoppedReactively = out.labelAfterScrollUp.includes('▶');
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

