  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('http://localhost:4214/#/virtual-scroller');
  await page.waitForTimeout(1500);
  const btn = page.locator('nav button', { hasText: 'autoplay' }).first();
  out.startsOn = (await btn.innerText()).includes('⏸');
  // probe actual content transform (translate3d or translateY)
  const probe = () => page.evaluate(() => {
    const els = [...document.querySelectorAll('.example-body *')].filter(el => /translate/.test(el.getAttribute('style') || ''));
    return els.length ? els[0].getAttribute('style').match(/-?[\d.]+px/g)?.join(',') : 'none';
  });
  const t0 = await probe();
  await page.waitForTimeout(3500);
  const t1 = await probe();
  out.creeps = t0 !== t1;
  out.t0 = t0; out.t1 = t1;
  // scroll up stops
  await page.locator('.example-body').hover();
  await page.mouse.wheel(0, -250);
  await page.waitForTimeout(600);
  out.stopsOnUp = (await btn.innerText()).includes('▶');
  // scroll down re-arms
  await page.mouse.wheel(0, 350);
  await page.waitForTimeout(800);
  out.rearmsOnDown = (await btn.innerText()).includes('⏸');
  // and creeps again after settling
  const t2 = await probe();
  await page.waitForTimeout(3000);
  const t3 = await probe();
  out.creepsAfterRearm = t2 !== t3;
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

