    const nameW = name.getBoundingClientRect().width;
    for (let size = 30; size >= 10; size -= 0.25) {
      sub.style.fontSize = size + 'px';
      if (sub.getBoundingClientRect().width <= nameW) break;
    }
    return { nameW: Math.round(nameW), subW: Math.round(sub.getBoundingClientRect().width), fontSize: sub.style.fontSize };
