### Ran Playwright code
```js
await (async (page) => {
  const hi = await page.context().browser().newContext({ deviceScaleFactor: 3 });
  const hiPage = await hi.newPage();
  await hiPage.goto('file:///tmp/claude-1000/-home-parallels-dev-ivue/566fe626-e30e-4195-b057-18d7724adbb0/scratchpad/lockup.html');
  await hiPage.waitForTimeout(1600);
  const result = await hiPage.evaluate(() => {
    const rightOfLastGlyph = (el) => {
      const node = el.childNodes[0];
      const range = document.createRange();
      range.setStart(node, node.length - 1);
      range.setEnd(node, node.length);
      return range.getBoundingClientRect().right;
    };
    const name = document.querySelector('.name');
    const sub = document.querySelector('.sub');
    const target = rightOfLastGlyph(name);
    let size = 30;
    for (; size >= 8; size -= 0.1) {
      sub.style.fontSize = size.toFixed(2) + 'px';
      if (rightOfLastGlyph(sub) <= target + 0.5) break;
    }
    return {
      nameRight: rightOfLastGlyph(name).toFixed(1),
      subRight: rightOfLastGlyph(sub).toFixed(1),
      fontSize: sub.style.fontSize,
    };
  });
  const el = hiPage.locator('#lockup');
  await el.screenshot({ path: '~/dev/ivue/docs_v2/public/brand-lockup-light.png', omitBackground: true, scale: 'device' });
  await hiPage.evaluate(() => { const l = document.getElementById('lockup'); l.classList.remove('light'); l.classList.add('dark'); });
  await hiPage.waitForTimeout(200);
  await el.screenshot({ path: '~/dev/ivue/docs_v2/public/brand-lockup-dark.png', omitBackground: true, scale: 'device' });
  await hi.close();
  return JSON.stringify(result);
})(page);
```

