async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.setViewportSize({ width: 1280, height: 900 });
  // playground: store-pattern is FIRST in sidebar
  await page.goto('http://localhost:4215/');
  await page.waitForTimeout(800);
  out.firstSidebarItem = await page.locator('.sidebar nav button .title').first().innerText();
  await page.goto('http://localhost:4215/#/store-pattern');
  await page.waitForTimeout(800);
  // add a task in TaskBoard, verify stats + reactive panel update (shared singleton)
  const input = page.locator('.board__add input');
  await input.fill('Light the engines');
  await input.press('Enter');
  await page.waitForTimeout(400);
  out.taskInList = (await page.locator('.board__list').innerText()).includes('Light the engines');
  out.statsAfterAdd = (await page.locator('.stats .vals').innerText()).replace(/\n/g,' | ');
  // toggle the new task done → stats progress changes everywhere
