  const tagSection = page.locator('.field-grid section', { hasText: 'Create new options' });
  const tagInput = tagSection.locator('input').first();
  // type an EXISTING tag name fully — no create row should appear
  await tagInput.click();
  await tagInput.pressSequentially('urgent', { delay: 25 });
  await page.waitForTimeout(1400);
  const menuExisting = await page.locator('.q-menu .q-item').allInnerTexts();
  out.existingShowsCreate = menuExisting.some(t => t.includes('Create new'));
  out.existingMenu = menuExisting.slice(0, 3);
  // clear and type a NEW name — create row should appear
  await tagInput.fill('');
  await tagInput.pressSequentially('brand-new-thing', { delay: 25 });
  await page.waitForTimeout(1400);
  const menuNew = await page.locator('.q-menu .q-item').allInnerTexts();
  out.newShowsCreate = menuNew.some(t => t.includes('Create new'));
  await page.keyboard.press('Escape');
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

