async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('about:blank');
  await page.goto('http://localhost:4180/ivue/');
  await page.waitForTimeout(1000);
  return await page.evaluate(() => {
    const vw = document.documentElement.clientWidth;
    const rows = [];
    const probe = (label, el) => {
      if (!el) return rows.push({ label, missing: true });
      const r = el.getBoundingClientRect();
      rows.push({ label, left: Math.round(r.left), right: Math.round(vw - r.right), width: Math.round(r.width) });
    };
    probe('hero inner', document.querySelector('.ivh-inner'));
    probe('statband', document.querySelector('.ix-statband'));
    probe('moat grid', document.querySelector('.ix-moat'));
    probe('idea section', document.querySelector('.ix-idea'));
    // whatever sections follow the moat
    const moat = document.querySelector('.ix-moat')?.closest('section');
    let after = moat?.nextElementSibling;
    let i = 0;
    while (after && i < 4) { probe('after-moat section ' + i, after); after = after.nextElementSibling; i++; }
    probe('.ix container', document.querySelector('.ix'));
    return JSON.stringify(rows, null, 1);
  });
}

