async (page) => {
  const ctx = await page.context().browser().newContext();
  const fresh = await ctx.newPage();
  await fresh.setViewportSize({ width: 1440, height: 900 });
  await fresh.goto('http://localhost:4180/ivue/', { waitUntil: 'networkidle' });
  const out = await fresh.evaluate(() => {
    const ix = document.querySelector('.ix');
    const r = ix.getBoundingClientRect();
    const cs = getComputedStyle(ix);
    // walk parents for constraining boxes
    const chain = [];
    let el = ix.parentElement;
    while (el && chain.length < 5) {
      const pr = el.getBoundingClientRect();
      const pcs = getComputedStyle(el);
      chain.push(`${el.className || el.tagName}: left=${Math.round(pr.left)} w=${Math.round(pr.width)} pad=${pcs.padding}`);
      el = el.parentElement;
    }
    return { ixLeft: Math.round(r.left), ixWidth: Math.round(r.width), ixPad: cs.padding, ixMax: cs.maxWidth, chain };
  });
  await ctx.close();
  return JSON.stringify(out, null, 1);
}

